insert into civic_votes (code, title, vote_date, pillar_code, chamber, source_url, alignment_note, total_for, total_against, total_abstain) values
  ('AN_ENR_2023', 'Loi accélération de la production d''énergies renouvelables', '2023-01-10', 'ENV', 'AN', 'https://www.assemblee-nationale.fr/dyn/16/scrutins/823', 'Voter POUR = soutien à ce texte d''accélération des renouvelables. Attention : plusieurs groupes de gauche ont voté CONTRE en le jugeant insuffisant — le vote est un fait, pas un jugement d''intention.', 286, 238, 38),
  ('AN_NUCLEAIRE_2023', 'Loi accélération du nucléaire', '2023-03-21', 'ENV', 'AN', 'https://www.assemblee-nationale.fr/dyn/16/scrutins/1243', 'Relance du nucléaire (énergie bas-carbone, mais contestée sur sûreté/déchets). Le sens du vote recouvre des motifs variés — on affiche le fait, pas une intention.', 402, 130, 8),
  ('EP_CARS_ZEV_2035_2023', 'Fin des voitures thermiques neuves en 2035 (normes CO₂)', '2023-02-14', 'ENV', 'EP', 'https://www.europarl.europa.eu/news/en/press-room/20230210IPR74715/fit-for-55-zero-co2-emissions-for-new-cars-and-vans-in-2035', 'Voter POUR = soutien à une contrainte climatique forte sur l''automobile (sens du pilier Environnement de DIAMS).', 340, 279, 21),
  ('EP_NATURE_RESTORATION_2024', 'Loi sur la restauration de la nature', '2024-02-27', 'ENV', 'EP', 'https://www.europarl.europa.eu/news/en/press-room/20240223IPR18078/', 'Voter POUR = soutien à une contrainte forte de restauration des écosystèmes (sens du pilier Environnement de DIAMS).', 329, 275, 24)
