--   entity_regimes           46
-- =============================================================================

begin;

-- Secteurs
on conflict (code) do update set
  name = excluded.name,
  description = excluded.description,
  animal_relevant = excluded.animal_relevant,
  wap_relevant = excluded.wap_relevant,
  inv_relevant = excluded.inv_relevant,
  plastic_relevant = excluded.plastic_relevant,
  water_relevant = excluded.water_relevant;

-- Piliers (dimensions)
on conflict (code) do update set
  name = excluded.name,
  description = excluded.description,
  default_weight = excluded.default_weight,
  display_order = excluded.display_order;

-- Méta-scores
on conflict (code) do update set
  name = excluded.name,
  description = excluded.description,
  display_order = excluded.display_order;

-- Membres des méta-scores
on conflict (group_id, dimension_id) do update set
  weight = excluded.weight;

-- Indicateurs
on conflict (code) do update set
  dimension_id = excluded.dimension_id,
  name = excluded.name,
  kind = excluded.kind,
  direction = excluded.direction,
  sector_specific = excluded.sector_specific,
  applies_to_sector_id = excluded.applies_to_sector_id,
  weight = excluded.weight,
  unit = excluded.unit,
  methodology = excluded.methodology;

-- Gates (plafonds de pilier)
on conflict (dimension_id) do update set
  gate_indicator_id = excluded.gate_indicator_id,
  default_ceiling = excluded.default_ceiling,
  notes = excluded.notes;

-- Sources
on conflict (code) do update set
  name = excluded.name,
  tier = excluded.tier,
  publisher = excluded.publisher,
  url = excluded.url,
  description = excluded.description;

-- Config méthodo : tiers de source
on conflict (tier) do update set
  evidence_weight = excluded.evidence_weight,
  max_confidence = excluded.max_confidence,
  can_penalize_alone = excluded.can_penalize_alone,
  min_score_floor_alone = excluded.min_score_floor_alone,
  notes = excluded.notes;

-- Config méthodo : nature des preuves
on conflict (nature) do update set
  score_multiplier = excluded.score_multiplier,
  max_score_without_result = excluded.max_score_without_result,
  notes = excluded.notes;

-- Config méthodo : paramètres
on conflict (key) do update set
  value = excluded.value,
  description = excluded.description;

-- Profils de valeurs
on conflict (code) do update set
  name = excluded.name,
  description = excluded.description,
  is_default = excluded.is_default;

-- Poids des profils
on conflict (profile_id, dimension_id) do update set
  weight = excluded.weight;

-- Entités (résolution : identifiants officiels)
on conflict (slug) do update set
  legal_name = excluded.legal_name,
  display_name = excluded.display_name,
  lei = excluded.lei,
  siren = excluded.siren,
  country = excluded.country,
  sector_id = excluded.sector_id,
  is_brand = excluded.is_brand,
  animal_free = excluded.animal_free;

