-- Obligations de publication : régimes (Règle 1)
on conflict (code) do update set
  name = excluded.name,
  jurisdiction = excluded.jurisdiction,
  legal_basis = excluded.legal_basis,
  scope = excluded.scope,
  url = excluded.url,
  in_force_since = excluded.in_force_since;

-- Obligations : indicateurs rendus obligatoires
on conflict (indicator_id, regime_id) do update set
  note = excluded.note;

-- Obligations : entités soumises (faits sourcés)
on conflict (entity_id, regime_id) do update set
  basis = excluded.basis,
  source_url = excluded.source_url,
  observed_on = excluded.observed_on,
  reviewer = excluded.reviewer;

-- Preuves (evidence) — clé : entité + indicateur + source + date
on conflict (entity_id, indicator_id, source_id, observed_on) do update set
  value_type = excluded.value_type,
  value_numeric = excluded.value_numeric,
  value_boolean = excluded.value_boolean,
  value_text = excluded.value_text,
  normalized_value = excluded.normalized_value,
  nature = excluded.nature,
  confidence = excluded.confidence,
  reviewer = excluded.reviewer,
  review_status = excluded.review_status,
  contested = excluded.contested,
  source_url = excluded.source_url,
  excerpt = excluded.excerpt;

-- Module civique : groupes politiques
on conflict (code) do update set
  name = excluded.name,
  short_name = excluded.short_name,
  chamber = excluded.chamber,
  seats = excluded.seats,
  ordinal = excluded.ordinal;

-- Module civique : votes
on conflict (code) do update set
